import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId) public {
        // Ensure tokenId is valid (not too large) – we'll just use it as is
        // Get default royaltyRecipient by checking after initialize (which sets it)
        // We need to initialize the contract with a royaltyRecipient.
        // Since C's initialize() is internal, we cannot call it directly.
        // But C inherits CreatorRoyaltiesControl which has public `royalties` mapping.
        // We can set the per-token royalty via updateRoyalties which is external but
        // we need an art creator. Simpler: we can just check any tokenId.
        // If per-token has royaltyRecipient == address(0), the reference C returns default.
        // The buggy version returns the per-token config instead.
        // So we need a per-token where royaltyRecipient == address(0) and royaltyBPS != 0.
        // We can directly set the storage via vm.store (it's a public mapping but no setter except updateRoyalties).
        // Use vm.store to set royalties[tokenId] to (royaltyBPS = 100, royaltyRecipient = address(0)).
        uint256 slot = uint256(keccak256(abi.encode(tokenId, uint256(0)))); // slot for mapping royalties
        // The mapping `royalties` is at slot 0 (first declared state variable in CreatorRoyaltiesControl).
        // But actual slot is determined by inheritance. We can compute it as:
        // storage slot = keccak256(abi.encode(tokenId, uint256(0))) + 0? No: for mapping, slot is keccak256(key . slot_of_mapping)
        // Simpler: use vm.store to set the specific token's RoyaltyConfiguration.
        // RoyaltyConfiguration is two 32-byte words (because packed? Actually it's a struct with uint32 and address – uint32 takes 1 slot, address takes 1 slot, total 2 slots).
        // Let's just set the first slot to royaltyBPS = 100 and second slot to address(0).
        // We need to find the storage slot of royalties mapping.
        // The CreatorRoyaltiesControl has `mapping(uint256 => RoyaltyConfiguration) public royalties;`
        // This mapping is stored at the slot after the previous state variables.
        // We can find it by checking the position: after `initilaized` bool (1 slot) and `royaltyRecipient` address (1 slot), then `royalties` mapping at slot 2.
        // So the base slot is 2.
        bytes32 baseSlot = bytes32(uint256(2));
        // For key = tokenId, storage slot = keccak256(abi.encode(key, baseSlot))
        bytes32 storageSlot = keccak256(abi.encode(tokenId, baseSlot));
        // Set royaltyBPS to 100 (non-zero), royaltyRecipient to address(0)
        vm.store(address(c), storageSlot, bytes32(uint256(100))); // royaltyBPS = 100
        vm.store(address(c), bytes32(uint256(storageSlot) + 1), bytes32(uint256(0))); // royaltyRecipient = address(0)

        // Now check getRoyalties – it should NOT return the per-token config when royaltyRecipient is zero.
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = c.getRoyalties(tokenId);
